target.css:
:root {
  --ink: #20333a;
  --muted: #6b7d80;
  --paper: #fffdf7;
  --aqua: #cdeeea;
  --teal: #167d78;
  --coral: #ef765f;
  --line: #b9d8d4;
}

.guide-card {
  box-sizing: border-box;
  width: 480px;
  padding: 16px;
  color: var(--ink);
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 18px;
}

.guide-card * {
  box-sizing: border-box;
}

.guide-card__header {
  display: flex;
  align-items: center;
  gap: 10px;
}

.guide-card__icon {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  font-size: 20px;
  background: var(--aqua);
  border-radius: 12px;
}

.guide-card__heading {
  flex: 1;
}

.guide-card__eyebrow {
  margin: 0 0 2px;
  color: var(--teal);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.guide-card h1 {
  margin: 0;
  font-size: 19px;
  line-height: 1.1;
}

.guide-card__status {
  padding: 5px 7px;
  color: var(--paper);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
  background: var(--coral);
  border-radius: 999px;
}

.guide-card__code {
  display: flex;
  align-items: baseline;
  gap: 9px;
  margin-top: 13px;
  padding: 10px 12px;
  background: var(--aqua);
  border-radius: 10px;
}

.guide-card__code span:first-child {
  color: var(--teal);
  font-size: 12px;
  font-weight: 700;
}

.guide-card__code strong {
  font-size: 22px;
  letter-spacing: 0.04em;
}

.guide-card__dots {
  margin-left: auto;
  color: var(--teal);
  font-size: 14px;
  letter-spacing: 2px;
}

.guide-card__details {
  display: grid;
  grid-template-columns: 1.35fr 1fr 0.8fr;
  gap: 8px;
  margin: 12px 0;
}

.guide-card__details section {
  padding-left: 9px;
  border-left: 2px solid var(--line);
}

.guide-card dt {
  margin-bottom: 3px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
}

.guide-card dd {
  margin: 0;
  font-size: 13px;
  font-weight: 700;
  line-height: 1.2;
}

.guide-card__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 10px;
  color: var(--muted);
  font-size: 12px;
  border-top: 1px solid var(--line);
}

.guide-card button {
  padding: 6px 10px;
  color: var(--paper);
  font: inherit;
  font-size: 12px;
  font-weight: 800;
  background: var(--teal);
  border: 0;
  border-radius: 7px;
}

